import os, sys, pty, select, time, fcntl, termios, struct, signal, subprocess, json

class Term:
    """Very small terminal emulator: tracks a grid + captures raw output."""
    def __init__(self, rows=30, cols=100):
        self.rows=rows; self.cols=cols
        self.raw=b''
        self.child=None

    def spawn(self, args, rows=30, cols=100, env=None):
        self.rows=rows; self.cols=cols
        pid, fd = pty.fork()
        if pid==0:
            if env:
                os.environ.update(env)
            os.execv(args[0], args)
            os._exit(1)
        self.pid=pid; self.fd=fd
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        return self

    def read(self, timeout=0.4):
        out=b''
        end=time.time()+timeout
        while True:
            rem=end-time.time()
            if rem<=0: break
            r,_,_=select.select([self.fd],[],[],rem)
            if r:
                try:
                    d=os.read(self.fd, 65536)
                except OSError:
                    break
                if not d: break
                out+=d
                end=time.time()+0.15
            else:
                break
        self.raw+=out
        return out

    def write(self, s):
        if isinstance(s,str): s=s.encode()
        os.write(self.fd, s)

    def close(self):
        try: os.kill(self.pid, signal.SIGKILL)
        except Exception: pass
        try: os.close(self.fd)
        except Exception: pass
        try: os.waitpid(self.pid,0)
        except Exception: pass
