import re

class Cell:
    __slots__=('ch','fg','bg','attrs')
    def __init__(self):
        self.ch=' '; self.fg=None; self.bg=None; self.attrs=frozenset()

class VT:
    def __init__(self, rows=30, cols=100):
        self.rows=rows; self.cols=cols
        self.grid=[[Cell() for _ in range(cols)] for _ in range(rows)]
        self.cx=0; self.cy=0
        self.fg=None; self.bg=None; self.attrs=set()
        self.alt=False
        self.cursor_visible=True
        self.title=None
        self.unknown=[]

    def resize(self, rows, cols):
        self.rows=rows; self.cols=cols
        self.grid=[[Cell() for _ in range(cols)] for _ in range(rows)]

    def clear(self):
        self.grid=[[Cell() for _ in range(self.cols)] for _ in range(self.rows)]

    def feed(self, data):
        if isinstance(data, bytes):
            data=data.decode('utf-8', 'replace')
        i=0; n=len(data)
        while i<n:
            c=data[i]
            if c=='\x1b':
                if i+1<n and data[i+1]=='[':
                    m=re.match(r'\x1b\[([\x30-\x3f]*)([\x20-\x2f]*)([\x40-\x7e])', data[i:])
                    if m:
                        self.csi(m.group(1), m.group(2), m.group(3))
                        i+=m.end(); continue
                    else:
                        i+=1; continue
                elif i+1<n and data[i+1]==']':
                    m=re.match(r'\x1b\](.*?)(\x07|\x1b\\)', data[i:], re.S)
                    if m:
                        self.title=m.group(1); i+=m.end(); continue
                    i+=1; continue
                elif i+1<n and data[i+1] in '()':
                    i+=3; continue
                elif i+1<n and data[i+1]=='=':
                    i+=2; continue
                elif i+1<n and data[i+1]=='>':
                    i+=2; continue
                else:
                    self.unknown.append(repr(data[i:i+4])); i+=1; continue
            elif c=='\r':
                self.cx=0; i+=1; continue
            elif c=='\n':
                self.cy+=1
                if self.cy>=self.rows: self.cy=self.rows-1
                i+=1; continue
            elif c=='\x08':
                self.cx=max(0,self.cx-1); i+=1; continue
            elif c=='\t':
                self.cx=min(self.cols-1,(self.cx//8+1)*8); i+=1; continue
            elif c<' ':
                i+=1; continue
            else:
                self.put(c); i+=1; continue

    def put(self, c):
        import unicodedata
        if self.cx>=self.cols:
            self.cx=0; self.cy=min(self.rows-1,self.cy+1)
        cell=self.grid[self.cy][self.cx]
        cell.ch=c; cell.fg=self.fg; cell.bg=self.bg; cell.attrs=frozenset(self.attrs)
        w=2 if unicodedata.east_asian_width(c) in ('W','F') else 1
        self.cx+=w
        if w==2 and self.cx-1<self.cols:
            c2=self.grid[self.cy][self.cx-1]
            c2.ch=''; c2.fg=self.fg; c2.bg=self.bg; c2.attrs=frozenset(self.attrs)

    def csi(self, params, inter, final):
        priv = params.startswith('?')
        ps = params[1:] if priv else params
        args=[int(x) if x else 0 for x in ps.split(';')] if ps else []
        def a(idx, default=1):
            return args[idx] if idx<len(args) and args[idx]!=0 else default
        if final=='H' or final=='f':
            self.cy=min(self.rows-1, a(0,1)-1); self.cx=min(self.cols-1, a(1,1)-1)
        elif final=='A': self.cy=max(0,self.cy-a(0,1))
        elif final=='B': self.cy=min(self.rows-1,self.cy+a(0,1))
        elif final=='C': self.cx=min(self.cols-1,self.cx+a(0,1))
        elif final=='D': self.cx=max(0,self.cx-a(0,1))
        elif final=='G': self.cx=min(self.cols-1,a(0,1)-1)
        elif final=='d': self.cy=min(self.rows-1,a(0,1)-1)
        elif final=='J':
            mode=args[0] if args else 0
            if mode==2 or mode==3:
                self.clear()
            elif mode==0:
                for x in range(self.cx,self.cols): self.grid[self.cy][x]=Cell()
                for y in range(self.cy+1,self.rows):
                    self.grid[y]=[Cell() for _ in range(self.cols)]
            elif mode==1:
                for y in range(0,self.cy): self.grid[y]=[Cell() for _ in range(self.cols)]
                for x in range(0,self.cx+1): self.grid[self.cy][x]=Cell()
        elif final=='K':
            mode=args[0] if args else 0
            if mode==0:
                for x in range(self.cx,self.cols): self.grid[self.cy][x]=Cell()
            elif mode==1:
                for x in range(0,self.cx+1): self.grid[self.cy][x]=Cell()
            else:
                self.grid[self.cy]=[Cell() for _ in range(self.cols)]
        elif final=='m':
            self.sgr(args if args else [0])
        elif final=='h':
            if priv:
                for v in args:
                    if v==1049: self.alt=True; self.clear()
                    if v==25: self.cursor_visible=True
        elif final=='l':
            if priv:
                for v in args:
                    if v==1049: self.alt=False; self.clear()
                    if v==25: self.cursor_visible=False
        else:
            self.unknown.append(('csi',params,inter,final))

    def sgr(self, args):
        i=0
        while i<len(args):
            v=args[i]
            if v==0:
                self.fg=None; self.bg=None; self.attrs=set()
            elif v==1: self.attrs.add('bold')
            elif v==2: self.attrs.add('dim')
            elif v==3: self.attrs.add('italic')
            elif v==4: self.attrs.add('underline')
            elif v==5: self.attrs.add('blink')
            elif v==7: self.attrs.add('reverse')
            elif v==9: self.attrs.add('strike')
            elif v==22: self.attrs.discard('bold'); self.attrs.discard('dim')
            elif v==23: self.attrs.discard('italic')
            elif v==24: self.attrs.discard('underline')
            elif v==27: self.attrs.discard('reverse')
            elif v==29: self.attrs.discard('strike')
            elif 30<=v<=37: self.fg=v-30
            elif v==39: self.fg=None
            elif 40<=v<=47: self.bg=v-40
            elif v==49: self.bg=None
            elif 90<=v<=97: self.fg=v-90+8
            elif 100<=v<=107: self.bg=v-100+8
            elif v==38 or v==48:
                if i+1<len(args) and args[i+1]==5:
                    val=('idx',args[i+2] if i+2<len(args) else 0); i+=2
                elif i+1<len(args) and args[i+1]==2:
                    val=('rgb',tuple(args[i+2:i+5])); i+=4
                else:
                    val=None
                if v==38: self.fg=val
                else: self.bg=val
            i+=1

    def text(self, strip=True):
        out=[]
        for row in self.grid:
            s=''.join(c.ch for c in row)
            out.append(s.rstrip() if strip else s)
        return '\n'.join(out)

    def styled(self):
        """Return list of rows, each a list of (text, fg, bg, attrs) runs."""
        rows=[]
        for row in self.grid:
            runs=[]
            cur=None
            for c in row:
                key=(c.fg,c.bg,c.attrs)
                if cur and cur[0]==key:
                    cur[1].append(c.ch)
                else:
                    cur=(key,[c.ch]); runs.append(cur)
            rows.append([(''.join(v),k[0],k[1],sorted(k[2])) for k,v in runs])
        return rows

    def dump_styles(self):
        out=[]
        for y,runs in enumerate(self.styled()):
            parts=[]
            for text,fg,bg,attrs in runs:
                if text.strip()=='' and not bg and not attrs: 
                    parts.append(repr(text))
                else:
                    parts.append('%r[fg=%s bg=%s %s]'%(text,fg,bg,','.join(attrs)))
            line=' '.join(parts)
            if line.strip(): out.append('%2d: %s'%(y,line))
        return '\n'.join(out)
