import os,pty,select,time,fcntl,termios,struct,signal,re,sys

def sample(args, rows=24, cols=100, timeout=3.0):
    """Spawn, wait for the lesson text, return the target string."""
    pid, fd = pty.fork()
    if pid==0:
        try:
            os.execv('/workspace/executable', ['/workspace/executable']+args)
        finally:
            os._exit(1)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    buf=b''
    end=time.time()+timeout
    res=None
    try:
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.05)
            if r:
                try: d=os.read(fd,65536)
                except OSError: break
                if not d: break
                buf+=d
                # look for the lesson-text write: \x1b[7;NNH\x1b[1m<text>
                m=re.search(rb'\x1b\[\d+;(\d+)H\x1b\[1m([^\x1b]+)\x1b\[', buf)
                if m:
                    res=m.group(2).decode('utf-8','replace')
                    break
    finally:
        try: os.kill(pid, signal.SIGKILL)
        except Exception: pass
        try: os.close(fd)
        except Exception: pass
        try: os.waitpid(pid,0)
        except Exception: pass
    return res

if __name__=='__main__':
    t0=time.time()
    for i in range(5):
        print(repr(sample(['--top','5','--combi','5','--rep','1','--nokb'])))
    print('avg %.3fs'%((time.time()-t0)/5))
